# (a|aa)*c matched against a^n by backtracking: count complete decompositions that each end with a failed attempt at c
def backtrack(n):
    count = 0
    def go(pos):
        nonlocal count
        if pos == n:
            count += 1          # all of a^n is consumed: try to match c, which fails (end of input)
            return
        if pos + 1 <= n:
            go(pos + 1)          # try a
        if pos + 2 <= n:
            go(pos + 2)          # then back up and try aa
    go(0)
    return count
