    h = {A: [] for A in g}
    count = {}
    cache = {}
    for A, rs in list(g.items()):
        for r in rs:
            while len(r) > 2:
                tail = r[1:]
                if tail not in cache:
                    cache[tail] = 'D' + str(len(cache) + 1)
                    h[cache[tail]] = []
                    h[cache[tail]].append(None)  # placeholder, filled below
                r = (r[0], cache[tail])
            if r not in h[A]:
