    return h


def reachable(g, S0):
    seen = {S0}
    todo = [S0]
    while todo:
        A = todo.pop()
        for r in g.get(A, []):
            for s in r:
                if s in g and s not in seen:
                    seen.add(s)
                    todo.append(s)
    return {A: rs for A, rs in g.items() if A in seen}


def language(g, start, maxlen=8):
    """All terminal strings of length <= maxlen derivable from start, by fixpoint on sets of strings."""
    L = {A: set() for A in g}
    ch = True
    while ch:
        ch = False
        for A, rs in g.items():
            for r in rs:
                parts = [{''}]
                for s in r:
                    if s in g:
                        parts.append(L[s])
                    else:
                        parts.append({s})
                cur = {''}
                for p in parts[1:]:
                    cur = {x + y for x in cur for y in p if len(x + y) <= maxlen}
                new = cur - L[A]
                if new:
                    L[A] |= new
                    ch = True
    return L[start]


