from itertools import product
results = {}
for n in (1, 2, 3):
    D = range(n)
    pairs = [(x, y) for x in D for y in D]
    holds_i = True
    found = []
    for bits in product([False, True], repeat=len(pairs)):
        R = {pr for pr, b in zip(pairs, bits) if b}
        ae = all(any((x, y) in R for y in D) for x in D)     # forall x exists y R(x,y)
        ea = any(all((x, y) in R for x in D) for y in D)     # exists y forall x R(x,y)
        if ea and not ae:
            holds_i = False
        if ae and not ea:
            found.append(sorted(R))
    results[n] = (holds_i, len(found), found[:1])
for n, (h, count, ex) in results.items():
    print('domain size', n, ': EA entails AE in every relation:', h, '; relations with AE true and EA false:', count, ex)
